package com.jykito.industrialcore.compat.kubejs;

import dev.latvian.mods.kubejs.event.EventGroupRegistry;
import dev.latvian.mods.kubejs.plugin.KubeJSPlugin;
import dev.latvian.mods.kubejs.script.ScriptType;

/**
 * KubeJS integration: the startup events for solar panels and the restructor.
 * Recipe schemas are data since KubeJS 7: data/industrial_core/kubejs/recipe_schema (generated by tools/port/kubejs_schemas.js).
 */
public class ICKubeJSPlugin implements KubeJSPlugin {

    @Override
    public void registerEvents(EventGroupRegistry registry) {
        registry.register(ICStartupEvents.GROUP);
    }

    @Override
    public void initStartup() {
        ICStartupEvents.SOLAR_PANEL.post(ScriptType.STARTUP, new SolarPanelEventJS());
        ICStartupEvents.RESTRUCTOR.post(ScriptType.STARTUP, new RestructorEventJS());
        ICStartupEvents.WIND_ROTOR.post(ScriptType.STARTUP, new WindRotorEventJS());
    }
}
